 1→'use client';
 2→
 3→import { ReactNode } from 'react';
 4→
 5→/**
 6→ * AccordionCategory - Expandable category section for PROCESS page
 7→ *
 8→ * COLOR HIERARCHY MANTRA:
 9→ * - Title expanded: --text-primary (brightest)
10→ * - Title collapsed: --grey-500 (medium)
11→ * - Chevron: --text-dim (dimmest)
12→ *
13→ * Information hierarchy = Color hierarchy
14→ */
15→
16→interface AccordionCategoryProps {
17→  title: string;
18→  count: number;
19→  isExpanded: boolean;
20→  onToggle: () => void;
21→  children: ReactNode;
22→  prefersReducedMotion?: boolean;
23→}
24→
25→export default function AccordionCategory({
26→  title,
27→  count,
28→  isExpanded,
29→  onToggle,
30→  children,
31→  prefersReducedMotion = false
32→}: AccordionCategoryProps) {
33→  return (
34→    <section className="mb-12 sm:mb-[72px]">
35→      {/* Section Header - Matches INFO page section labels */}
36→      {/* min-h-[44px] ensures touch-friendly tap target */}
37→      <button
38→        onClick={onToggle}
39→        className="w-full text-left flex items-center gap-4 cursor-pointer group min-h-[44px]"
40→        style={{ marginBottom: isExpanded ? '36px' : '0' }}
41→        aria-expanded={isExpanded}
42→      >
43→        {/* Title - PRIMARY when expanded, SECONDARY when collapsed */}
44→        <h2
45→          style={{
46→            color: isExpanded ? 'var(--text-primary)' : 'var(--grey-500)',
47→            fontFamily: 'var(--font-lora)',
48→            fontStyle: 'italic',
49→            fontWeight: 400,
50→            fontSize: 'clamp(22px, 2.2vw, 28px)',
51→            lineHeight: 1.15,
52→            letterSpacing: '0.005em',
53→            transition: prefersReducedMotion ? 'none' : 'color 250ms ease'
54→          }}
55→        >
56→          {title}
57→        </h2>
58→
59→        {/* Chevron - TERTIARY */}
60→        <svg
61→          width="14"
62→          height="14"
63→          viewBox="0 0 12 12"
64→          fill="none"
65→          stroke="currentColor"
66→          strokeWidth="1.5"
67→          strokeLinecap="round"
68→          style={{
69→            color: isExpanded ? 'var(--grey-500)' : 'var(--text-dim)',
70→            transform: isExpanded ? 'rotate(180deg)' : 'rotate(0deg)',
71→            transition: prefersReducedMotion ? 'none' : 'transform 300ms cubic-bezier(0.4, 0, 0.2, 1), color 250ms ease'
72→          }}
73→        >
74→          <path d="M2 4L6 8L10 4" />
75→        </svg>
76→      </button>
77→
78→      {/* Expandable Content - CSS Grid for smooth height animation */}
79→      <div
80→        style={{
81→          display: 'grid',
82→          gridTemplateRows: isExpanded ? '1fr' : '0fr',
83→          opacity: isExpanded ? 1 : 0,
84→          transition: prefersReducedMotion
85→            ? 'none'
86→            : 'grid-template-rows 350ms cubic-bezier(0.4, 0, 0.2, 1), opacity 250ms ease'
87→        }}
88→      >
89→        <div style={{ overflow: 'hidden' }}>
90→          {children}
91→        </div>
92→      </div>
93→    </section>
94→  );
95→}
