126→/**
127→ * Parse message text and extract project slugs
128→ * Returns array of { type: 'text' | 'project', content: string }
129→ */
130→export function parseMessageWithProjects(text: string): Array<{ type: 'text' | 'project'; content: string }> {
131→  const parts: Array<{ type: 'text' | 'project'; content: string }> = [];
132→  const projectRegex = /\[PROJECT:([a-z0-9-]+)\]/gi;
133→
134→  let lastIndex = 0;
135→  let match;
136→
137→  while ((match = projectRegex.exec(text)) !== null) {
138→    // Add text before the match
139→    if (match.index > lastIndex) {
140→      parts.push({
141→        type: 'text',
142→        content: text.slice(lastIndex, match.index)
143→      });
144→    }
145→
146→    // Add the project reference
147→    parts.push({
148→      type: 'project',
149→      content: match[1] // The slug
150→    });
151→
152→    lastIndex = match.index + match[0].length;
153→  }
154→
155→  // Add remaining text
156→  if (lastIndex < text.length) {
157→    parts.push({
158→      type: 'text',
159→      content: text.slice(lastIndex)
160→    });
161→  }
162→
163→  return parts.length > 0 ? parts : [{ type: 'text', content: text }];
164→}
