  3→import { useEffect, useState } from 'react';
  4→
  5→type CursorState = 'default' | 'link' | 'video' | 'button';
  6→
  7→export function CustomCursor() {
  8→  const [position, setPosition] = useState({ x: -100, y: -100 });
  9→  const [cursorState, setCursorState] = useState<CursorState>('default');
 10→  const [isVisible, setIsVisible] = useState(false);
 11→  const [animationKey, setAnimationKey] = useState(0);
 12→  const [isOverMetatag, setIsOverMetatag] = useState(false);
 13→  const [currentVideoSlug, setCurrentVideoSlug] = useState<string | null>(null);
 14→  const [isPressed, setIsPressed] = useState(false);
 15→
 16→  useEffect(() => {
 17→    // Check if device supports hover (desktop only)
 18→    const hasHover = window.matchMedia('(hover: hover) and (pointer: fine)').matches;
 19→    if (!hasHover) return;
 20→
 21→    setIsVisible(true);
 22→
 23→    const updateCursor = (e: MouseEvent) => {
 24→      setPosition({ x: e.clientX, y: e.clientY });
 25→
 26→      // Always use normal browser cursor
 27→      setIsOverMetatag(true);
 28→      setCursorState('default');
 29→      setCurrentVideoSlug(null);
 30→    };
 31→
 32→    window.addEventListener('mousemove', updateCursor);
 33→
 34→    return () => {
 35→      window.removeEventListener('mousemove', updateCursor);
 36→    };
 37→  }, [cursorState]);
 38→
 39→  // Trigger animation when entering video hover state, and repeat continuously every 3 seconds
 40→  // Watch currentVideoSlug so animation retriggers when moving between different videos
 41→  useEffect(() => {
 42→    let animationInterval: NodeJS.Timeout | null = null;
 43→
 44→    if (cursorState === 'video' && currentVideoSlug) {
 45→      // Trigger initial animation immediately on EVERY video entry (including switching between videos)
 46→      setAnimationKey(prev => prev + 1);
 47→
 48→      // Set interval to continuously repeat animation every 3 seconds while hovering
 49→      animationInterval = setInterval(() => {
 50→        setAnimationKey(prev => prev + 1);
 51→      }, 3000);
 52→    }
 53→
 54→    // Cleanup interval if user leaves video hover
 55→    return () => {
 56→      if (animationInterval) {
 57→        clearInterval(animationInterval);
 58→      }
 59→    };
 60→  }, [cursorState, currentVideoSlug]);
 61→
 62→  if (!isVisible) return null;
 63→
 64→  // Cursor properties based on state
 65→  const getCursorProps = () => {
 66→    switch (cursorState) {
 67→      case 'video':
 68→        return {
 69→          width: 'auto',
 70→          height: 'auto',
 71→          padding: '0.25rem 0.625rem', // Match metatag padding (py-1 px-2.5)
 72→          color: '#181818', // Dark grey background (matches site)
 73→          text: 'play',
 74→          fontSize: '11px',
 75→          fontWeight: 600, // Semibold weight
 76→          letterSpacing: '0.04em', // Subtle letter spacing
 77→          textColor: '#f5f5f5', // Project title color
 78→          fontFamily: 'var(--font-display)', // Match site font
 79→          borderRadius: '6px' // Match metatag rounded-md
 80→        };
 81→      case 'link':
 82→        return {
 83→          width: 20,
 84→          height: 20,
 85→          padding: '0',
 86→          color: '#6a6a6a',
 87→          text: '.',
 88→          fontSize: '20px',
 89→          fontWeight: 400,
 90→          letterSpacing: '0',
 91→          textColor: '#d9d9d9',
 92→          fontFamily: 'var(--font-dm-sans), -apple-system, BlinkMacSystemFont, sans-serif',
 93→          borderRadius: '2px'
 94→        };
 95→      case 'button':
 96→        return {
 97→          width: 20,
 98→          height: 20,
 99→          padding: '0',
100→          color: '#4a4a4a',
101→          text: '.',
102→          fontSize: '20px',
103→          fontWeight: 400,
104→          letterSpacing: '0',
105→          textColor: '#d9d9d9',
106→          fontFamily: 'var(--font-dm-sans), -apple-system, BlinkMacSystemFont, sans-serif',
107→          borderRadius: '2px'
108→        };
109→      default:
110→        return {
111→          width: 20,
112→          height: 20,
113→          padding: '0',
114→          color: '#8a8a8a',
115→          text: '.',
116→          fontSize: '20px',
117→          fontWeight: 400,
118→          letterSpacing: '0',
119→          textColor: '#d9d9d9',
120→          fontFamily: 'var(--font-dm-sans), -apple-system, BlinkMacSystemFont, sans-serif',
121→          borderRadius: '2px'
122→        };
123→    }
124→  };
125→
126→  const { width, height, padding, color, text, fontSize, fontWeight, letterSpacing, textColor, fontFamily, borderRadius } = getCursorProps();
127→
128→  // Lighten colors when pressed (dark background needs to brighten)
129→  const activeBackgroundColor = isPressed && cursorState === 'video' ? '#303030' : color;
130→  const activeTextColor = isPressed && cursorState === 'video' ? '#ffffff' : textColor;
131→
132→  return (
133→    <>
134→
135→      {/* Filled pill cursor with text */}
136→      <div
137→        style={{
138→          position: 'fixed',
139→          left: 0,
140→          top: 0,
141→          width: typeof width === 'number' ? `${width}px` : width,
142→          height: typeof height === 'number' ? `${height}px` : height,
143→          padding: padding,
144→          backgroundColor: activeBackgroundColor,
145→          opacity: isOverMetatag ? 0 : 1,
146→          pointerEvents: 'none',
147→          transform: `translate(${position.x}px, ${position.y}px) translate(-50%, -50%)`,
148→          transition: 'width 0.3s cubic-bezier(0.16, 1, 0.3, 1), height 0.3s cubic-bezier(0.16, 1, 0.3, 1), background-color 0.1s ease-out, transform 0.04s ease-out, opacity 0.2s ease-out',
149→          zIndex: 9999,
150→          willChange: 'transform, width, height, background-color',
151→          borderRadius: borderRadius,
152→          display: 'flex',
153→          alignItems: 'center',
154→          justifyContent: 'center',
155→          color: activeTextColor,
156→          fontFamily: fontFamily,
157→          fontSize: fontSize,
158→          fontWeight: fontWeight,
159→          letterSpacing: letterSpacing,
160→          textTransform: cursorState === 'video' ? 'uppercase' : 'none',
161→          userSelect: 'none',
162→          overflow: 'hidden',
163→          perspective: '200px'
164→        }}
165→      >
166→        <span
167→          key={animationKey}
168→          style={{
169→            opacity: 1,
170→            lineHeight: 1,
171→            animation: cursorState === 'video' ? 'filmReelRotate 0.8s cubic-bezier(0.45, 0, 0.55, 1) forwards' : 'none',
172→            transformStyle: 'preserve-3d'
173→          }}
174→        >
175→          {text}
176→        </span>
177→      </div>
178→    </>
179→  );
180→}
