  1→'use client';
  2→
  3→/**
  4→ * Perception Sensor
  5→ * Phase 2: USD Substrate Integration
  6→ *
  7→ * Tracks cursor movement, scrolling, and clicks at optimized sample rates.
  8→ * Now supports shared classifier via external event recorder.
  9→ */
 10→
 11→import { useEffect, useRef, useCallback } from 'react';
 12→import { SensorEvent, SensorEventType } from '@/lib/perception/types';
 13→
 14→interface PerceptionSensorProps {
 15→  // External event recorder (from context) - enables shared classifier
 16→  recordEvent: (event: Omit<SensorEvent, 'sessionId'>) => void;
 17→  // Session ID from context
 18→  sessionId: string;
 19→}
 20→
 21→export function PerceptionSensor({ recordEvent, sessionId }: PerceptionSensorProps) {
 22→  const lastCursorSampleRef = useRef<number>(0);
 23→  const lastScrollSampleRef = useRef<number>(0);
 24→  const lastScrollYRef = useRef<number>(0);
 25→  const pageViewStartRef = useRef<number>(Date.now());
 26→  const isInitializedRef = useRef(false);
 27→
 28→  /**
 29→   * Record initial page view on mount
 30→   */
 31→  useEffect(() => {
 32→    if (!sessionId || isInitializedRef.current) return;
 33→    isInitializedRef.current = true;
 34→
 35→    recordEvent({
 36→      timestamp: Date.now(),
 37→      type: SensorEventType.PAGE_VIEW,
 38→      data: {
 39→        dwellTime: 0,
 40→      },
 41→    });
 42→
 43→    return () => {
 44→      // Record final page view with dwell time
 45→      const dwellTime = Date.now() - pageViewStartRef.current;
 46→      recordEvent({
 47→        timestamp: Date.now(),
 48→        type: SensorEventType.PAGE_VIEW,
 49→        data: { dwellTime },
 50→      });
 51→    };
 52→  }, [sessionId, recordEvent]);
 53→
 54→  /**
 55→   * Cursor tracking - sampled at 30Hz (every ~33ms)
 56→   */
 57→  useEffect(() => {
 58→    if (!sessionId) return;
 59→
 60→    const handleMouseMove = (e: MouseEvent) => {
 61→      const now = Date.now();
 62→      if (now - lastCursorSampleRef.current < 33) return; // 30Hz throttle
 63→
 64→      lastCursorSampleRef.current = now;
 65→      recordEvent({
 66→        timestamp: now,
 67→        type: SensorEventType.CURSOR_MOVE,
 68→        data: {
 69→          x: e.clientX,
 70→          y: e.clientY,
 71→        },
 72→      });
 73→    };
 74→
 75→    window.addEventListener('mousemove', handleMouseMove, { passive: true });
 76→    return () => window.removeEventListener('mousemove', handleMouseMove);
 77→  }, [sessionId, recordEvent]);
 78→
 79→  /**
 80→   * Scroll tracking - sampled at 60Hz with velocity calculation
 81→   */
 82→  useEffect(() => {
 83→    if (!sessionId) return;
 84→
 85→    const handleScroll = () => {
 86→      const now = Date.now();
 87→      if (now - lastScrollSampleRef.current < 16) return; // 60Hz throttle
 88→
 89→      const scrollY = window.scrollY;
 90→      const deltaTime = now - lastScrollSampleRef.current;
 91→      const deltaScroll = scrollY - lastScrollYRef.current;
 92→
 93→      // Calculate scroll velocity in px/s
 94→      const scrollVelocity = deltaTime > 0 ? Math.abs(deltaScroll / deltaTime * 1000) : 0;
 95→
 96→      lastScrollSampleRef.current = now;
 97→      lastScrollYRef.current = scrollY;
 98→
 99→      recordEvent({
100→        timestamp: now,
101→        type: SensorEventType.SCROLL,
102→        data: {
103→          scrollY,
104→          scrollVelocity,
105→        },
106→      });
107→    };
108→
109→    window.addEventListener('scroll', handleScroll, { passive: true });
110→    return () => window.removeEventListener('scroll', handleScroll);
111→  }, [sessionId, recordEvent]);
112→
113→  /**
114→   * Click tracking - capture all clicks with target identification
115→   */
116→  useEffect(() => {
117→    if (!sessionId) return;
118→
119→    const handleClick = (e: MouseEvent) => {
120→      const target = e.target as HTMLElement;
121→      const targetDescription = target.tagName.toLowerCase() +
122→        (target.className ? `.${target.className.split(' ')[0]}` : '');
123→
124→      // Check if click is on a project card or detail link
125→      const projectSlug = target.closest('[data-project-slug]')?.getAttribute('data-project-slug');
126→
127→      recordEvent({
128→        timestamp: Date.now(),
129→        type: SensorEventType.CLICK,
130→        data: {
131→          x: e.clientX,
132→          y: e.clientY,
133→          target: targetDescription,
134→          projectSlug: projectSlug || undefined,
135→        },
136→      });
137→    };
138→
139→    window.addEventListener('click', handleClick);
140→    return () => window.removeEventListener('click', handleClick);
141→  }, [sessionId, recordEvent]);
142→
143→  // Sensor runs silently, renders nothing
144→  return null;
145→}
