  1→'use client';
  2→
  3→import { useEffect, useRef, useState, useCallback } from 'react';
  4→import type { VimeoPlayerType as Player } from '@/lib/vimeo';
  5→import { loadVimeoPlayer } from '@/lib/vimeo';
  6→import { useIsMobile } from '@/lib/hooks/useIsMobile';
  7→import { usePrefersReducedMotion } from '@/lib/hooks/usePrefersReducedMotion';
  8→
  9→/**
 10→ * PROJECT HERO REEL - Project Page Autoplay Video
 11→ *
 12→ * Mirrors homepage HeroReel behavior with:
 13→ * - Fixed position at top (70vh desktop, 50vh mobile)
 14→ * - Cinematic fade-in entrance with subtle scale
 15→ * - Scroll-based fade out and pause/resume
 16→ * - NO thumbnail overlay (pure video, background mode)
 17→ * - Mobile optimization: static thumbnail only (no video player)
 18→ */
 19→
 20→// Timeout for player initialization (12 seconds - supports slow connections)
 21→const INIT_TIMEOUT_MS = 12000;
 22→
 23→interface ProjectHeroReelProps {
 24→  videoId: string;
 25→  videoHash?: string;
 26→  startTime?: number;
 27→  thumbnail?: string;
 28→}
 29→
 30→export function ProjectHeroReel({ videoId, videoHash, startTime = 0 }: ProjectHeroReelProps) {
 31→  const containerRef = useRef<HTMLDivElement>(null);
 32→  const playerRef = useRef<Player | null>(null);
 33→  const isReadyRef = useRef(false);
 34→  const scrolledDownRef = useRef(false);
 35→
 36→  const [scrollProgress, setScrollProgress] = useState(0);
 37→  const [heroRevealed, setHeroRevealed] = useState(false);
 38→  const [videoPlaying, setVideoPlaying] = useState(false);
 39→
 40→  const { isMobile, isReady: isMobileReady } = useIsMobile();
 41→  const prefersReducedMotion = usePrefersReducedMotion();
 42→
 43→  // Hero height based on device
 44→  const heroHeight = isMobile ? '50vh' : '70vh';
 45→
 46→  // Clean destroy of player instance
 47→  const destroyPlayer = useCallback(() => {
 48→    if (playerRef.current) {
 49→      try {
 50→        playerRef.current.destroy();
 51→      } catch {
 52→        // Player may already be destroyed
 53→      }
 54→      playerRef.current = null;
 55→    }
 56→    isReadyRef.current = false;
 57→  }, []);
 58→
 59→  // Reveal hero after navigation settles (creates cinematic entrance sequence)
 60→  useEffect(() => {
 61→    const revealTimer = setTimeout(() => setHeroRevealed(true), 400);
 62→    return () => clearTimeout(revealTimer);
 63→  }, []);
 64→
 65→  // Initialize Vimeo player with autoplay (desktop only)
 66→  useEffect(() => {
 67→    // Wait for mobile detection to complete before deciding
 68→    if (!isMobileReady) return;
 69→
 70→    // Skip player initialization on mobile - use static thumbnail instead
 71→    if (isMobile) return;
 72→
 73→    if (!containerRef.current) return;
 74→
 75→    const baseConfig = {
 76→      muted: true,
 77→      loop: true,
 78→      autoplay: true,
 79→      controls: false,
 80→      background: true,
 81→      responsive: true,
 82→      title: false,
 83→      byline: false,
 84→      portrait: false,
 85→      dnt: true,
 86→      playsinline: true,
 87→      quality: 'auto',
 88→      speed: true,
 89→      transparent: false,
 90→    };
 91→
 92→    const baseUrl = videoHash
 93→      ? `https://vimeo.com/${videoId}/${videoHash}`
 94→      : `https://vimeo.com/${videoId}`;
 95→    const urlWithTime = startTime > 0 ? `${baseUrl}#t=${startTime}s` : baseUrl;
 96→
 97→    let isMounted = true;
 98→
 99→    const initPlayer = async () => {
100→      try {
101→        const VimeoPlayer = await loadVimeoPlayer();
102→        if (!isMounted || !containerRef.current) return;
103→
104→        playerRef.current = new VimeoPlayer(containerRef.current!, {
105→          url: urlWithTime as `https://vimeo.com/${string}`,
106→          ...baseConfig
107→        });
108→
109→        // Race between ready() and timeout
110→        const readyPromise = playerRef.current.ready();
111→        const timeoutPromise = new Promise<never>((_, reject) => {
112→          setTimeout(() => reject(new Error('ProjectHeroReel initialization timeout')), INIT_TIMEOUT_MS);
113→        });
114→
115→        await Promise.race([readyPromise, timeoutPromise]);
116→
117→        if (!isMounted) {
118→          destroyPlayer();
119→          return;
120→        }
121→
122→        isReadyRef.current = true;
123→
124→        // Add error event listener for runtime failures
125→        playerRef.current.on('error', (error) => {
126→          console.error('ProjectHeroReel: Player error', videoId, error);
127→        });
128→
129→        // Wait for video to actually start rendering frames before revealing
130→        const revealOnce = () => {
131→          if (isMounted) setVideoPlaying(true);
132→        };
133→        playerRef.current.on('bufferend', revealOnce);
134→        playerRef.current.on('playing', revealOnce);
135→
136→        // Start playback (may already be playing via background autoplay)
137→        await playerRef.current.play().catch(() => {});
138→      } catch (err) {
139→        console.error('ProjectHeroReel: Player init failed', videoId, err);
140→        destroyPlayer();
141→      }
142→    };
143→
144→    initPlayer();
145→
146→    return () => {
147→      isMounted = false;
148→      destroyPlayer();
149→    };
150→  }, [videoId, videoHash, startTime, destroyPlayer, isMobile, isMobileReady]);
151→
152→  // Track scroll for fade and pause/resume
153→  useEffect(() => {
154→    const handleScroll = () => {
155→      const scrollY = window.scrollY;
156→      const viewportHeight = window.innerHeight;
157→      // Use appropriate hero height multiplier based on device
158→      const heroHeightValue = viewportHeight * (isMobile ? 0.5 : 0.7);
159→
160→      // Fade out over 300px starting when content appears
161→      const fadeStartScroll = heroHeightValue * 0.3;
162→      const fadeRange = 300;
163→      const progress = Math.max(0, Math.min((scrollY - fadeStartScroll) / fadeRange, 1));
164→      setScrollProgress(progress);
165→
166→      // Pause/resume with ref tracking for consistency (desktop only)
167→      if (!isMobile) {
168→        const hasScrolledDown = scrollY > 10;
169→
170→        if (hasScrolledDown && !scrolledDownRef.current) {
171→          scrolledDownRef.current = true;
172→          if (playerRef.current && isReadyRef.current) {
173→            playerRef.current.pause().catch(() => {});
174→          }
175→        } else if (!hasScrolledDown && scrolledDownRef.current) {
176→          scrolledDownRef.current = false;
177→          if (playerRef.current && isReadyRef.current) {
178→            playerRef.current.play().catch(() => {});
179→          }
180→        }
181→      }
182→    };
183→
184→    // Run immediately to sync initial state
185→    handleScroll();
186→
187→    window.addEventListener('scroll', handleScroll, { passive: true });
188→    return () => window.removeEventListener('scroll', handleScroll);
189→  }, [isMobile]);
190→
191→  const scrollOpacity = 1 - scrollProgress;
192→  const heroOpacity = heroRevealed ? scrollOpacity : 0;
193→  const heroScale = heroRevealed ? 1 : 1.02;
194→  const transitionDuration = prefersReducedMotion ? '0ms' : '1.2s';
195→  const transitionEasing = 'cubic-bezier(0.16, 1, 0.3, 1)';
196→
197→  // Transition strategy: opacity only animates during initial reveal, then becomes instant for scroll
198→  // This ensures scroll-driven fade is perfectly synchronized with navigation
199→  const heroTransition = heroRevealed
200→    ? `transform ${transitionDuration} ${transitionEasing}, filter ${transitionDuration} ${transitionEasing}`
201→    : `opacity ${transitionDuration} ${transitionEasing}, transform ${transitionDuration} ${transitionEasing}, filter ${transitionDuration} ${transitionEasing}`;
202→
203→  return (
204→    <div
205→      className="fixed top-0 left-0 right-0 w-full overflow-hidden"
206→      style={{
207→        height: heroHeight,
208→        zIndex: 0,
209→        backgroundColor: '#141414',
210→        viewTransitionName: 'hero-reel',
211→      }}
212→    >
213→      <div
214→        style={{
215→          width: '100%',
216→          height: '100%',
217→          opacity: heroOpacity,
218→          transform: `scale(${heroScale})`,
219→          filter: heroRevealed ? 'saturate(1) brightness(1)' : 'saturate(0.3) brightness(0.6)',
220→          transition: heroTransition,
221→          transformOrigin: 'center center',
222→          willChange: heroRevealed ? 'auto' : 'opacity, transform, filter'
223→        }}
224→      >
225→        {!isMobile && (
226→          // Desktop: Vimeo player container (behind thumbnail until video plays)
227→          <div
228→            ref={containerRef}
229→            className="absolute inset-0 w-full h-full"
230→            style={{
231→              backgroundColor: '#141414',
232→              zIndex: 0
233→            }}
234→          />
235→        )}
236→        {/* Dark overlay - sits ABOVE iframe, matches site background until video plays.
237→            Video emerges seamlessly from the page background. */}
238→        <div
239→          className="absolute inset-0 w-full h-full"
240→          style={{
241→            backgroundColor: '#141414',
242→            zIndex: 1,
243→            opacity: videoPlaying ? 0 : 1,
244→            transition: 'opacity 0.4s ease-out',
245→            pointerEvents: 'none'
246→          }}
247→        />
248→      </div>
249→    </div>
250→  );
251→}
