  1→'use client';
  2→
  3→import { createContext, useContext, useCallback, useRef, ReactNode } from 'react';
  4→
  5→/**
  6→ * VIDEO THUMBNAIL MANAGER - Single Active Video Coordinator
  7→ *
  8→ * Ensures only one video plays at a time across the entire grid.
  9→ * Prevents race conditions by:
 10→ * 1. Stopping ALL registered videos when a new one activates (not just "active" one)
 11→ * 2. Providing isActive() check for videos to verify status before playing
 12→ * 3. Synchronous stop calls to minimize timing windows
 13→ *
 14→ * Inspired by ThinkingMachines determinism principles:
 15→ * Same cursor movement → Same video state → Deterministic playback
 16→ */
 17→
 18→interface VideoController {
 19→  stop: () => void;
 20→  id: string;
 21→}
 22→
 23→interface VideoThumbnailContextValue {
 24→  registerVideo: (id: string, stop: () => void) => void;
 25→  unregisterVideo: (id: string) => void;
 26→  activateVideo: (id: string) => void;
 27→  deactivateVideo: (id: string) => void;
 28→  isActive: (id: string) => boolean;
 29→}
 30→
 31→const VideoThumbnailContext = createContext<VideoThumbnailContextValue | null>(null);
 32→
 33→export function VideoThumbnailManager({ children }: { children: ReactNode }) {
 34→  const activeIdRef = useRef<string | null>(null);
 35→  const controllersRef = useRef<Map<string, VideoController>>(new Map());
 36→
 37→  const registerVideo = useCallback((id: string, stop: () => void) => {
 38→    controllersRef.current.set(id, { id, stop });
 39→  }, []);
 40→
 41→  const unregisterVideo = useCallback((id: string) => {
 42→    controllersRef.current.delete(id);
 43→    if (activeIdRef.current === id) {
 44→      activeIdRef.current = null;
 45→    }
 46→  }, []);
 47→
 48→  const activateVideo = useCallback((id: string) => {
 49→    // CRITICAL: Stop ALL other videos, not just the "active" one
 50→    // This handles race conditions where multiple videos might be initializing
 51→    controllersRef.current.forEach((controller, controllerId) => {
 52→      if (controllerId !== id) {
 53→        controller.stop();
 54→      }
 55→    });
 56→    activeIdRef.current = id;
 57→  }, []);
 58→
 59→  const deactivateVideo = useCallback((id: string) => {
 60→    if (activeIdRef.current === id) {
 61→      const controller = controllersRef.current.get(id);
 62→      if (controller) {
 63→        controller.stop();
 64→      }
 65→      activeIdRef.current = null;
 66→    }
 67→  }, []);
 68→
 69→  const isActive = useCallback((id: string) => {
 70→    return activeIdRef.current === id;
 71→  }, []);
 72→
 73→  return (
 74→    <VideoThumbnailContext.Provider
 75→      value={{
 76→        registerVideo,
 77→        unregisterVideo,
 78→        activateVideo,
 79→        deactivateVideo,
 80→        isActive
 81→      }}
 82→    >
 83→      {children}
 84→    </VideoThumbnailContext.Provider>
 85→  );
 86→}
 87→
 88→export function useVideoThumbnailManager() {
 89→  const context = useContext(VideoThumbnailContext);
 90→  if (!context) {
 91→    throw new Error('useVideoThumbnailManager must be used within VideoThumbnailManager');
 92→  }
 93→  return context;
 94→}
 95→
 96→// Optional hook for components outside the provider (graceful fallback)
 97→export function useOptionalVideoThumbnailManager() {
 98→  return useContext(VideoThumbnailContext);
 99→}
